# ruff: noqa: E501, PT018
"""T-004-024: design-code provenance attribute on every generated prim and the manifest label.

Requirements: FR-004-20.

Oracle: the expected attribute values are written in this test (`pitstudio:provenance = "design-code"`, the label text
"regenerated by design code, not observed"); the layer is read back with OpenUSD (reference implementation); the
manifest entry is validated with the DC-004-02 draft schema and its digest recomputed with hashlib.

Expected API (package `pitstudio_studio.scene.design`, studio environment):
- `design.usd.write_design_layer(path, result, *, rel_path="layers/design.usda") -> dict` writes the `.usda` design
  layer of a `DesignResult` (test_t_004_023) with the default prim `World` and the prim `/World/Design`; every prim under
  `/World/Design` (itself included) carries the string attribute `pitstudio:provenance = "design-code"`; every geometry
  prim has a `SemanticsLabelsAPI:class` label from {bench, berm, ramp, windrow, haul_road}; `upAxis = "Z"`,
  `metersPerUnit = 1.0`, `kilogramsPerUnit = 1.0` are authored; siblings are authored in sorted name order. It returns
  the DC-004-02 `layers[]` entry of the layer: `role` "design", `path` = `rel_path`, `format` "usda", `sha256`, `bytes`,
  `up_axis`, `meters_per_unit`, `kilograms_per_unit` and `label` "regenerated by design code, not observed".
"""

from __future__ import annotations

import hashlib
import json
import sys
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / "studio" / "src"))
sys.path.insert(0, str(ROOT / "tests" / "_scene_kit"))
import scene_kit as kit  # noqa: E402
from pitstudio_studio.scene import design  # noqa: E402

LABEL = "regenerated by design code, not observed"
KINDS = {"bench", "berm", "ramp", "windrow", "haul_road"}


@pytest.fixture(scope="module")
def built(tmp_path_factory: pytest.TempPathFactory):
    grid = kit.flat_grid(130.0, 1.0, 0.0)
    spec = kit.design_spec(h=12.0, alpha=70.0, b=10.0, g=8.0, w=20.0, windrow=2.5, floor_z=-36.0)
    res = design.build_design(grid, spec, outline_xy=kit.regular_polygon(180, 100.0))
    path = tmp_path_factory.mktemp("design") / "design.usda"
    entry = design.usd.write_design_layer(path, res, rel_path="layers/design.usda")
    return path, res, entry


@pytest.mark.req("FR-004-20")
def test_every_generated_prim_carries_the_design_code_provenance(built) -> None:
    from pxr import Usd

    path, _, _ = built
    stage = Usd.Stage.Open(str(path))
    root = stage.GetPrimAtPath("/World/Design")
    assert root.IsValid()
    prims = list(Usd.PrimRange(root))
    assert len(prims) > 10
    for prim in prims:
        attr = prim.GetAttribute("pitstudio:provenance")
        assert attr.IsValid(), f"{prim.GetPath()} has no provenance"
        assert attr.Get() == "design-code"
        assert attr.GetNumTimeSamples() == 0


@pytest.mark.req("FR-004-20")
def test_geometry_prims_have_one_class_label_from_the_design_kinds(built) -> None:
    from pxr import Usd, UsdGeom, UsdSemantics

    path, _, _ = built
    stage = Usd.Stage.Open(str(path))
    seen = set()
    for prim in Usd.PrimRange(stage.GetPrimAtPath("/World/Design")):
        if prim.IsA(UsdGeom.Gprim):
            labels = list(UsdSemantics.LabelsAPI(prim, "class").GetLabelsAttr().Get())
            assert len(labels) == 1 and labels[0] in KINDS, (prim.GetPath(), labels)
            seen.add(labels[0])
    assert seen == KINDS  # benches, berms, ramp, windrows and haul roads are all generated


@pytest.mark.req("FR-004-20")
def test_layer_units_and_sorted_authoring_order(built) -> None:
    from pxr import Sdf

    path, _, _ = built
    layer = Sdf.Layer.FindOrOpen(str(path))
    assert layer.pseudoRoot.GetInfo("upAxis") == "Z"
    assert layer.pseudoRoot.GetInfo("metersPerUnit") == 1.0
    assert layer.pseudoRoot.GetInfo("kilogramsPerUnit") == 1.0
    assert layer.defaultPrim == "World"

    def children_sorted(spec) -> None:
        names = [c.name for c in spec.nameChildren]
        assert names == sorted(names), (spec.path, names)
        for child in spec.nameChildren:
            children_sorted(child)

    children_sorted(layer.pseudoRoot)


@pytest.mark.req("FR-004-20")
def test_manifest_layer_entry_carries_the_label_and_a_correct_digest(built) -> None:
    path, _, entry = built
    data = Path(path).read_bytes()
    assert entry == {
        "role": "design",
        "path": "layers/design.usda",
        "format": "usda",
        "sha256": hashlib.sha256(data).hexdigest(),
        "bytes": len(data),
        "up_axis": "Z",
        "meters_per_unit": 1.0,
        "kilograms_per_unit": 1.0,
        "label": LABEL,
    }
    manifest = json.loads((kit.EXAMPLES / "scene-manifest.valid.json").read_text(encoding="utf-8"))
    manifest["layers"] = [entry if layer["role"] == "design" else layer for layer in manifest["layers"]]
    assert kit.schema_errors("scene-manifest.schema.json", manifest) == []


@pytest.mark.req("FR-004-20")
def test_report_and_road_network_carry_the_same_provenance(built) -> None:
    _, res, _ = built
    assert res.report["provenance"] == "design-code" and res.report["label"] == LABEL
    assert res.road_network["provenance"] == "design-code"
